<?php use MediaPitch\Core\Csrf; $editing=!empty($category); ?>
<div class="two-col">
<section class="panel"><div class="panel-head"><div><h2>Categories</h2><p>Database-driven catalog structure.</p></div></div>
<table class="data-table"><thead><tr><th>Name</th><th>Parent</th><th>Slug</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach($categories as $c):?><tr><td><?= e($c['name']) ?></td><td><?= e($c['parent_name'] ?? '—') ?></td><td><code><?= e($c['slug']) ?></code></td><td><?= !empty($c['active'])?'Active':'Inactive' ?></td><td><div class="inline-actions"><a href="<?= e(url('admin/categories?edit='.(int)$c['id'])) ?>">Edit</a><form method="post" action="<?= e(url('admin/categories/'.(int)$c['id'].'/'.(!empty($c['active'])?'archive':'restore'))) ?>" onsubmit="return confirm('<?= !empty($c['active'])?'Archive this category? Products remain stored but the category becomes unavailable publicly.':'Restore this category?' ?>')"><?= Csrf::field() ?><button class="link-button"><?= !empty($c['active'])?'Archive':'Restore' ?></button></form></div></td></tr><?php endforeach;?>
<?php if(!$categories):?><tr><td colspan="5" class="empty">No categories yet.</td></tr><?php endif;?>
</tbody></table></section>
<section class="panel"><h2><?= $editing?'Edit category':'Add category' ?></h2><form method="post" action="<?= e(url('admin/categories/save')) ?>" class="stack-form"><?= Csrf::field() ?><?php if($editing):?><input type="hidden" name="id" value="<?= (int)$category['id'] ?>"><?php endif;?><label>Name<input name="name" required value="<?= e($category['name']??'') ?>"></label><label>Slug<input name="slug" required value="<?= e($category['slug']??'') ?>"></label><label>Parent<select name="parent_id"><option value="">None</option><?php foreach($categoryOptions as $c): if($editing&&(int)$c['id']===(int)$category['id'])continue;?><option value="<?= (int)$c['id'] ?>" <?= (int)($category['parent_id']??0)===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach;?></select></label><label>Description<textarea name="description" rows="4"><?= e($category['description']??'') ?></textarea></label><label>SEO title<input name="seo_title" value="<?= e($category['seo_title']??'') ?>"></label><label>Meta description<textarea name="meta_description" rows="3"><?= e($category['meta_description']??'') ?></textarea></label><label>Sort order<input type="number" name="sort_order" value="<?= e((string)($category['sort_order']??0)) ?>"></label><label class="check"><input type="checkbox" name="active" value="1" <?= !isset($category['active'])||!empty($category['active'])?'checked':'' ?>> Active</label><div class="form-actions"><?php if($editing):?><a class="secondary-button" href="<?= e(url('admin/categories')) ?>">Cancel</a><?php endif;?><button class="primary-button">Save category</button></div></form></section></div>